'use strict';

/**
* BLAS level 2 routine to perform the matrix-vector operation `y = alpha*A*x + beta*y` for a symmetric matrix `A`.
*
* @module @stdlib/blas/base/ndarray/dsymv
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float64Array = require( '@stdlib/array/float64' );
* var dsymv = require( '@stdlib/blas/base/ndarray/dsymv' );
*
* var A = new ndarray( 'float64', new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 1.0, 2.0, 3.0, 2.0, 1.0 ] ), [ 3, 3 ], [ 3, 1 ], 0, 'row-major' );
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var y = new Float64Vector( [ 4.0, 5.0, 6.0 ] );
*
* var alpha = scalar2ndarray( 3.0, {
*     'dtype': 'float64'
* });
* var beta = scalar2ndarray( 2.0, {
*     'dtype': 'float64'
* });
*
* var out = dsymv( [ A, x, y, alpha, beta ] );
* // returns <ndarray>[ 50.0, 40.0, 42.0 ]
*
* var bool = ( out === y );
* // returns true
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
